<?php if($wallet): ?><section class="comm-card" id="usage"><h2>Credit usage</h2><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Date (UTC)</th><th>Entry</th><th>Credits</th><th>Balance</th><th>Message</th></tr></thead><tbody><?php $entries=0;foreach($comm['ledger'] as $r):if($r['channel']!==$channel)continue;$entries++; ?><tr><td><?= $h($r['created_at']); ?></td><td><?= $status_text($r['note']); ?></td><td><?= $r['units']>0?'+':''; ?><?= number_format($r['units']); ?></td><td><?= number_format($r['balance_units']); ?></td><td><?= $r['message_id']?'#'.(int)$r['message_id']:'—'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$entries): ?><p class="empty">Your credit activity will appear here.</p><?php endif; ?><div class="row"><?php $historyPage=(int)($comm['history_page']??0);if($historyPage>0): ?><a class="btn secondary" href="<?= $workspace_url('history',array('history_page'=>$historyPage-1)).'#usage'; ?>">Newer entries</a><?php endif; ?><?php if(!empty($comm['history_has_more'])): ?><a class="btn secondary" href="<?= $workspace_url('history',array('history_page'=>$historyPage+1)).'#usage'; ?>">Older entries</a><?php endif; ?></div><details><summary>Message results · latest 50</summary><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Message</th><th>Recipient</th><th>Purpose</th><th>Credits</th><th>Sending / delivery</th></tr></thead><tbody><?php foreach($messaging['messages'] as $msg):if($msg['channel']!==$channel)continue; ?><tr><td>#<?= (int)$msg['id']; ?></td><td><?= $h($msg['recipient']); ?></td><td><?= $h($msg['category']); ?></td><td><?= $msg['category']==='platform'?0:(int)$msg['units']; ?></td><td><?= $h($msg['status'].' / '.str_replace('_',' ',$msg['delivery_status'])); ?></td></tr><?php endforeach; ?></tbody></table></div></details></section><?php endif; ?>

